INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Trends > Anwendung von IT-Systemen auf neue Einsatzgebiete prüfen
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Prüfung neuer Einsatzgebiete für IT-Systeme ohne Marktanalyse möglich?', 2, '[{"text": "Nein", "correct": true, "because": "Marktanalyse liefert wesentliche Daten zur Machbarkeit"}, {"text": "Ja", "correct": false, "because": "Ohne Analyse fehlt die Grundlage"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen neue Einsatzgebiete für IT-Systeme immer mit neuen Technologien verbunden sein?', 2, '[{"text": "Nein", "correct": true, "because": "Bestehende Technologien können neue Anwendungen finden"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Prüfung neuer Einsatzgebiete für IT-Systeme gesellschaftliche Bedürfnisse ignorieren?', 2, '[{"text": "Nein", "correct": true, "because": "Gesellschaftliche Bedürfnisse bestimmen oft die Relevanz"}, {"text": "Ja", "correct": false, "because": "Bedürfnisse sind entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Prüfung neuer Einsatzgebiete für IT-Systeme immer mit hohen Kosten verbunden?', 2, '[{"text": "Nein", "correct": true, "because": "Kosten variieren je nach Methode und Umfang"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig teuer"}]'),
('00000000-0000-0000-0000-000000000000', 'Können neue Einsatzgebiete für IT-Systeme durch Kundenfeedback identifiziert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Kundenfeedback zeigt oft unerfüllte Bedürfnisse"}, {"text": "Nein", "correct": false, "because": "Feedback ist eine valide Quelle"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Methode ist am effektivsten, um neue Einsatzgebiete für IT-Systeme zu prüfen?', 2, '[{"text": "Machbarkeitsstudien", "correct": true, "because": "Bewerten technische und wirtschaftliche Aspekte"}, {"text": "Zufällige Tests", "correct": false, "because": "Unstrukturiert"}, {"text": "Interne Umfragen", "correct": false, "because": "Begrenzt extern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor ist bei der Prüfung neuer Einsatzgebiete für IT-Systeme am wichtigsten?', 3, '[{"text": "Marktnachfrage", "correct": true, "because": "Bestimmt wirtschaftlichen Erfolg"}, {"text": "Technische Neuerung", "correct": false, "because": "Nicht immer nötig"}, {"text": "Mitarbeiterschulung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Einsatzgebiet wurde durch IT-Systeme in den letzten Jahren stark erweitert?', 2, '[{"text": "Smart Home", "correct": true, "because": "IoT hat Anwendung verbreitert"}, {"text": "Manuelle Buchhaltung", "correct": false, "because": "Keine Erweiterung"}, {"text": "Papierbasierte Kommunikation", "correct": false, "because": "Veraltet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ressource ist für die Prüfung neuer Einsatzgebiete unerlässlich?', 2, '[{"text": "Marktdaten", "correct": true, "because": "Liefern Nachfrage und Trends"}, {"text": "Produktionskapazität", "correct": false, "because": "Später relevant"}, {"text": "Marketingbudget", "correct": false, "because": "Nachgelagert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Risiko entsteht, wenn neue Einsatzgebiete unzureichend geprüft werden?', 2, '[{"text": "Fehlinvestitionen", "correct": true, "because": "Ressourcen werden verschwendet"}, {"text": "Geringere Produktivität", "correct": false, "because": "Indirekt"}, {"text": "Technischer Stillstand", "correct": false, "because": "Nicht primär"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sollten bei der Prüfung neuer Einsatzgebiete für IT-Systeme berücksichtigt werden?', 4, '[{"text": "Technische Machbarkeit", "correct": true, "because": "Bestimmt Umsetzbarkeit"}, {"text": "Wirtschaftliche Rentabilität", "correct": true, "because": "Sichert Erfolg"}, {"text": "Gesellschaftliche Akzeptanz", "correct": true, "because": "Beeinflusst Nutzung"}, {"text": "Mitarbeiterpräferenzen", "correct": false, "because": "Weniger entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden eignen sich zur Prüfung neuer Einsatzgebiete für IT-Systeme?', 3, '[{"text": "Prototypentwicklung", "correct": true, "because": "Testet Funktionalität"}, {"text": "Marktanalysen", "correct": true, "because": "Zeigt Bedarf"}, {"text": "Kundenbefragungen", "correct": true, "because": "Erkennt Wünsche"}, {"text": "Werbekampagnen", "correct": false, "because": "Nachgelagert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einsatzgebiete wurden durch IT-Systeme kürzlich erweitert?', 4, '[{"text": "Telemedizin", "correct": true, "because": "Fernüberwachung"}, {"text": "Smart Cities", "correct": true, "because": "IoT-Anwendung"}, {"text": "E-Learning", "correct": true, "because": "Online-Bildung"}, {"text": "Manuelle Lagerhaltung", "correct": false, "because": "Keine Erweiterung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken gibt es bei der Prüfung neuer Einsatzgebiete für IT-Systeme?', 3, '[{"text": "Hohe Kosten", "correct": true, "because": "Tests können teuer sein"}, {"text": "Technische Grenzen", "correct": true, "because": "Nicht alles umsetzbar"}, {"text": "Fehlende Nachfrage", "correct": true, "because": "Markt kann ausbleiben"}, {"text": "Geringere Qualität", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren fördern die Identifikation neuer Einsatzgebiete für IT-Systeme?', 3, '[{"text": "Technologische Fortschritte", "correct": true, "because": "Ermöglichen Neues"}, {"text": "Kundenanforderungen", "correct": true, "because": "Zeigen Bedarf"}, {"text": "Markttrends", "correct": true, "because": "Leiten Richtung"}, {"text": "Produktionszeiten", "correct": false, "because": "Weniger relevant"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Marktanalysen sind für die Prüfung neuer Einsatzgebiete essenziell. b) Gesellschaftliche Bedürfnisse sind unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Analysen ja, Bedürfnisse relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Neue Einsatzgebiete können bestehende Technologien nutzen. b) Prüfung ist immer teuer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bestehende Technik ja, Kosten variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Kundenfeedback hilft, neue Einsatzgebiete zu finden. b) Technische Machbarkeit ist irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Feedback ja, Machbarkeit entscheidend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Prototypen testen neue Einsatzgebiete effektiv. b) Markttrends sind für die Prüfung unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prototypen ja, Trends relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Fehlinvestitionen sind ein Risiko bei unzureichender Prüfung. b) Neue Einsatzgebiete erfordern immer hohe Kosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fehlinvestitionen ja, Kosten variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

